public class Produto {
    private readonly string _moeda = "BRL";
    public static int TotalCriados { get; private set; }

    public required string Nome { get; init; }
    public decimal Preco { get; private set; }
    public int Estoque { get; set; }

    public Produto() => TotalCriados++;

    public void AplicarDesconto(decimal valor) {
        if (valor > 0) Preco -= valor;
    }

    public static string FormatarMoeda() => "BRL";
}

var p = new Produto { Nome = "Monitor", Estoque = 5 };

